        assertEquals(HttpStatus.BAD_REQUEST, failed.status());
        // 失败回滚不占键
        assertNull(reviewDedupOrNull(requestId));
        // 键未被占用：同键可成功用于合法请求
        MutationResponse ok = service.createZone(
