private List<String> stalenessReasons(ReviewPo po) {
    List<String> reasons = new ArrayList<>();
    RoutePo currentRoute = routeRepo.findRoute(po.routeId());
    if (currentRoute == null || currentRoute.version() != po.routeVersion()) reasons.add("ROUTE_VERSION_CHANGED");
    if (airspaceRepo.getGlobalVersion() != po.airspaceVersion()) reasons.add("AIRSPACE_VERSION_CHANGED");
    if (weatherRepo.getDutyVersion() != po.dutyVersion()) reasons.add("WEATHER_DUTY_VERSION_CHANGED");
    long latestForecast = weatherRepo.getLatestForecastVersion();
    Long frozen = po.forecastVersion();
    if (frozen == null ? latestForecast != 0 : frozen != latestForecast) reasons.add("FORECAST_VERSION_CHANGED");
    return reasons;
}
