    @Test
    void minimaRevisionMakesOldClearStaleButNeverRewrites() {
        service.configureWeatherRegion(regionReq("wr1", List.of(win(1000, 2000, 500, 300))));
        service.uploadForecast(forecastReq(fentry("wr1", 1000, 2000, 800, 400)));
